// Clean : aplatit la liste OpenSlice et sort un item par service avec juste l'id
const input = $input.all();
const specs = [];
for (const it of input) {
  const j = it.json;
  if (Array.isArray(j)) specs.push(...j);
  else if (j && Array.isArray(j.data)) specs.push(...j.data);
  else if (j) specs.push(j);
}

const kindOf = (s) => {
  const t = (s['@type'] || '').toLowerCase();
  if (t.includes('customerfacing')) return 'CFS';
  if (t.includes('resourcefacing')) return 'RFS';
  if (s.resourceSpecification && s.resourceSpecification.length) return 'RFS';
  const n = (s.name || '').toLowerCase();
  return (n.startsWith('rfs') || n.includes('@osm')) ? 'RFS' : 'CFS';
};

return specs
  .filter(s => s && s.id)
  .map((s, i) => ({
    json: { id: s.id, name: s.name, kind: kindOf(s) },
    pairedItem: { item: i },
  }));

// Nettoie le spec OpenSlice pour le rendre conforme au contrat de l'API,
// et fixe @type pour le routage / l'auto-détection.
// Mode : Run Once for All Items

const CFS = 'CustomerFacingServiceSpecification';
const RFS = 'ResourceFacingServiceSpecification';

// Supprime récursivement les clés 'uuid' et toutes les valeurs null/undefined
function clean(value) {
  if (Array.isArray(value)) return value.map(clean);
  if (value && typeof value === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(value)) {
      if (k === 'uuid') continue;                  // champ OpenSlice interdit
      if (v === null || v === undefined) continue; // null rejeté par le contrat
      out[k] = clean(v);
    }
    return out;
  }
  return value;
}

const isRFS = (s) => {
  const t = (s['@type'] || '').toLowerCase();
  if (t.includes('resourcefacing')) return true;
  if (t.includes('customerfacing')) return false;
  const n = (s.name || '').toLowerCase();
  if (n.startsWith('rfs') || n.includes('_rfs') || n.includes('@osm')) return true;
  const cats = (s.category || []).map(c => (c.name || '').toLowerCase()).join(' ');
  if (cats.includes('resource')) return true;
  if (cats.includes('customer')) return false;
  const hasRes = Array.isArray(s.resourceSpecification) && s.resourceSpecification.length > 0;
  const hasRel = Array.isArray(s.serviceSpecRelationship) && s.serviceSpecRelationship.length > 0;
  return hasRes && !hasRel;
};

return $input.all().map((it, i) => {
  const spec = clean(it.json);
  spec['@type'] = isRFS(spec) ? RFS : CFS;
  if (typeof spec.href !== 'string') spec.href = '';   // évite href:null
  return { json: spec, pairedItem: { item: i } };
});

// Toutes les requêtes CFS ont été effectuées avant cette vérification.
// Seul le conflit entity_already_exists est ignoré ; les autres erreurs restent visibles.
const results = [];
const errors = [];
for (const [i, item] of $input.all().entries()) {
  const statusCode = Number(item.json.statusCode);
  let body = item.json.body ?? item.json.data ?? null;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch { /* Préserver les réponses texte. */ }
  }
  const detail = body && typeof body === 'object' ? (body.detail ?? body) : body;
  const duplicate = statusCode === 409 &&
    detail && typeof detail === 'object' && detail.error_code === 'entity_already_exists';
  const success = statusCode >= 200 && statusCode < 300;
  if (!success && !duplicate) {
    const message = typeof detail === 'string' ? detail : JSON.stringify(detail);
    errors.push(`CFS item ${i + 1} : HTTP ${statusCode || 'inconnu'} — ${message}`);
  }
  results.push({
    json: {
      status: duplicate ? 'ignored_existing' : success ? 'created' : 'error',
      statusCode,
      response: body,
    },
    pairedItem: { item: i },
  });
}
if (errors.length) {
  const created = results.filter(r => r.json.status === 'created').length;
  const ignored = results.filter(r => r.json.status === 'ignored_existing').length;
  throw new Error(`CFS : ${created} ajouté(s), ${ignored} existant(s) ignoré(s), ${errors.length} erreur(s).\n${errors.join('\n')}`);
}
return results;
